function attractions(string $q='',string $category=''):array {
 $where='a.publicado=1';$params=[];
 if($q!==''){$where.=' AND (a.nombre LIKE ? OR a.descripcion LIKE ?)';$params[]='%'.$q.'%';$params[]='%'.$q.'%';}
 if($category!==''){$where.=' AND a.categoria_id=?';$params[]=$category;}
 return rows("SELECT a.*,c.nombre AS categoria,u.latitud,u.longitud,u.verificado AS posicion_verificada,(SELECT f.url FROM fotografias f WHERE f.atractivo_id=a.id AND f.verificado=1 ORDER BY f.id LIMIT 1) AS foto FROM atractivos_turisticos a JOIN categorias c ON c.id=a.categoria_id LEFT JOIN ubicaciones u ON u.id=a.ubicacion_id WHERE $where ORDER BY a.verificado DESC,a.nombre LIMIT 100",$params);
}
function card(array $a):void { ?><article class="place-card"><a class="card-art" href="<?=e(url('?page=atractivo&id='.$a['id']))?>"><?php if($a['foto']&&valid_https($a['foto'])):?><img src="<?=e($a['foto'])?>" alt="<?=e($a['nombre'])?>" loading="lazy" referrerpolicy="no-referrer"><?php else:?><img src="<?=e(url('assets/landscape.svg'))?>" alt="Ilustración artística de un paisaje andino; no es una fotografía del atractivo" loading="lazy"><span class="art-label">ILUSTRACIÓN REFERENCIAL</span><?php endif;?></a><div class="card-body"><div class="card-top"><span class="eyebrow"><?=e($a['categoria'])?></span><?=badge((bool)$a['verificado'])?></div><h3><a href="<?=e(url('?page=atractivo&id='.$a['id']))?>"><?=e($a['nombre'])?></a></h3><p><?=e(mb_strimwidth($a['descripcion'],0,190,'…'))?></p><a class="text-link" href="<?=e(url('?page=atractivo&id='.$a['id']))?>">Conocer el lugar <span>→</span></a></div></article><?php }
