 directa desde tu ubicación y, si hay proveedor disponible, solicitar una ruta.</p></aside></div><div class="section-heading"><h2>Inventario turístico</h2><span class="muted">Máximo 100 resultados por búsqueda</span></div><div class="cards three"><?php foreach($items as $a)card($a);if(!$items):?><p class="empty">No hay lugares para estos filtros. Prueba otro nombre o categoría.</p><?php endif;?></div></section><?php
}
function detail_page():void {
 $id=filter_var(query_string('id'),FILTER_VALIDATE_INT);$a=one('SELECT a.*,c.nombre categoria,u.latitud,u.longitud,u.altitud_m,u.precision_m,u.verificado posicion_verificada FROM atractivos_turisticos a JOIN categorias c ON c.id=a.categoria_id LEFT JOIN ubicaciones u ON u.id=a.ubicacion_id WHERE a.id=? AND a.publicado=1',[$id?:0]);
 if(!$a)fail_page('Lugar no encontrado','Esta ficha no existe o aún no está publicada.',404);
 $key=$a['id'].'-'.date('Y-m-d');if(empty($_SESSION['views'][$key])){execute('INSERT INTO visitas(atractivo_id,usuario_id) VALUES(?,?)',[$a['id'],current_user()['id']??null]);$_SESSION['views']=array_slice($_SESSION['views']??[],-99,null,true);$_SESSION['views'][$key]=true;}
 page($a['nombre'],function()use($a){$photos=rows('SELECT * FROM fotografias WHERE atractivo_id=? AND verificado=1 ORDER BY id',[$a['id']]);?><section class="container section"><a class="text-link" href="<?=e(url('?page=explorar'))?>">← Volver al inventario</a><div class="detail-heading"><div><span class="eyebrow"><?=e($a['categoria'])?></span><h1><?=e($a['nombre'])?></h1></div><?=badge((bool)$a['verificado'])?></div><div class="detail-grid"><article><div class="detail-art"><img src="<?=e($photos[0]['url']??url('assets/landscape.svg'))?>" alt="<?=e($photos[0]['descripcion']??'Ilustración artística referencial, no fotografía del sitio')?>"></div><?php if(!$photos):?><p class="muted small-text">Ilustración artística. Fotografía documental pendiente de incorporación y licencia.</p><?php endif;?><h2>Un lugar por conocer</h2><p class="prose"><?=nl2br(e($a['descripcion']))?></p><h3>Antes de tu visita</h3><p class="prose"><?=nl2br(e($a['recomendaciones']?:'Recomendaciones de acceso pendientes de verificación.'))?></p><?php foreach($photos as $photo):?><figure><img class="gallery-image" loading="lazy" src="<?=e($photo['url'])?>" alt="<?=e($photo['descripcion'])?>"><figcaption><?=e($photo['descripcion'])?> · <?=e($photo['autor'])?> · <?=e($photo['licencia'])?> <?=source_link($photo['fuente_url'])?></figcaption></figure><?php endforeach;?></article><aside class="info-panel"><span class="eyebrow">INFORMACIÓN DEL LUGAR</span><h3>Planifica con confianza.</h3><p>Distrito de Chavín de Huántar<br>Huari · Áncash · Perú</p><?php if($a['posicion_verificada']&&$a['verificado']):?><dl><dt>Latitud</dt><dd><?=e($a['latitud'])?></dd><dt>Longitud</dt><dd><?=e($a['longitud'])?></dd><dt>Altitud</dt><dd><?=$a['altitud_m']!==null?e($a['altitud_m']).' m':'No registrada'?></dd><dt>Precisión declarada</dt><dd><?=$a['precision_m']!==null?e($a['precision_m']).' m':'No registrada'?></dd></dl><a class="button" href="<?=e(url('?page=explorar#lugar-'.$a['id']))?>">Ver en mapa →</a><?php else:?><p class="notice">Coordenadas pendientes de verificación. Este lugar todavía no se representa en el mapa.</p><?php endif;?><hr><h4>Fuente documental</h4><?=source_link($a['fuente_url'])?><p class="muted small-text">Última edición: <?=e($a['actualizado_en'])?> (hora de Perú). El estado de la ficha no certifica horarios ni condiciones actuales de acceso.</p></aside></div></section><?php });
}
