 $type=query_string('tipo');$types=['hotel'=>'Alojamiento','restaurante'=>'Restaurantes','transporte'=>'Transporte'];$sql='SELECT * FROM servicios_turisticos WHERE publicado=1';$p=[];if(isset($types[$type])){$sql.=' AND tipo=?';$p[]=$type;}$items=rows($sql.' ORDER BY nombre LIMIT 100',$p);
?><section class="container page-intro"><span class="eyebrow">ACOMPAÑAMOS TU VIAJE</span><h1>Planifica tu estadía.</h1><p>Directorio local de alojamientos, restaurantes y transporte con fuentes consultables.</p></section><section class="container section compact"><div class="tabs"><a href="<?=e(url('?page=directorio'))?>" <?=$type===''?'aria-current="page"':''?>>Todos</a><?php foreach($types as $k=>$v):?><a href="<?=e(url('?page=directorio&tipo='.$k))?>" <?=$k===$type?'aria-current="page"':''?>><?=e($v)?></a><?php endforeach;?></div><div class="cards three"><?php foreach($items as $s):?><article class="info-panel"><span class="eyebrow"><?=e($types[$s['tipo']])?></span><h2><?=e($s['nombre'])?></h2><?=badge((bool)$s['verificado'])?><p><?=nl2br(e($s['descripcion']))?></p><p><?=e($s['direccion'])?></p><p><?=e($s['telefono'])?></p><?php if(valid_https($s['sitio_web']??'')):?><a href="<?=e($s['sitio_web'])?>" rel="noopener noreferrer" target="_blank">Sitio web →</a><?php endif;?><p><?=source_link($s['fuente_url'])?></p></article><?php endforeach;?></div><?php if(!$items):?><div class="empty"><span class="empty-icon">⌂</span><h2>Estamos preparando el directorio.</h2><p>Todavía no hay servicios publicados para esta categoría. No mostramos negocios ni teléfonos sin una fuente documental.</p><a class="text-link" href="<?=e(url('?page=explorar'))?>">Explorar el inventario →</a></div><?php endif;?></section><?php
}
function routes_page():void {
 $routes=rows('SELECT * FROM rutas_turisticas WHERE publicado=1 ORDER BY nombre LIMIT 100');
?><section class="container page-intro"><span class="eyebrow">EL VIAJE TAMBIÉN ES EL CAMINO</span><h1>Caminos con historia.</h1><p>Itinerarios peatonales y vehiculares documentados. Revisa siempre las condiciones actuales antes de salir.</p></section><section class="container section compact"><?php if(!$routes):?><div class="empty"><span class="empty-icon">↝</span><h2>Las buenas rutas se documentan.</h2><p>Aún no hay itinerarios publicados. Puedes explorar el mapa; el cálculo de una ruta necesita coordenadas verificadas y un proveedor configurado.</p><a class="button" href="<?=e(url('?page=explorar'))?>">Ir al mapa →</a></div><?php endif;foreach($routes as $r):$points=rows('SELECT p.orden,u.* FROM puntos_ruta p JOIN ubicaciones u ON u.id=p.ubicacion_id WHERE p.ruta_id=? ORDER BY p.orden',[$r['id']]);$valid=(bool)$r['verificado']&&count($points)>=2&&!array_filter($points,fn($p)=>!$p['verificado']);$distance=0;for($i=1;$i<count($points);$i++)$distance+=haversine($points[$i-1],$points[$i]);?><article class="info-panel route-card"><div><span class="eyebrow"><?=e($r['modo'])?></span><h2><?=e($r['nombre'])?></h2><?=badge((bool)$r['verificado'])?><p><?=nl2br(e($r['descripcion']))?></p><?=source_link($r['fuente_url'])?></div><div><?php if($valid):?><ol><?php foreach($points as $p):?><li><?=e($p['nombre'])?> <small><?=e($p['latitud'])?>, <?=e($p['longitud'])?></small></li><?php endforeach;?></ol><p><?=number_format($distance,2)?> km entre puntos en línea recta; no es la distancia de camino.</p><p><?=$r['duracion_min']!==null?e($r['duracion_min']).' minutos estimados por la fuente.':'Tiempo de recorrido pendiente de documentación.'?></p><?php else:?><p class="notice">Trazado pendiente de verificación: se necesitan al menos dos puntos comprobados. No se publica una ruta geográfica provisional.</p><?php endif;?></div></article><?php endforeach;?></section><?php
}
function haversine(array $a,array $b):float {$dlat=deg2rad((float)$b['latitud']-(float)$a['latitud']);$dlon=deg2rad((float)$b['longitud']-(float)$a['longitud']);$x=sin($dlat/2)**2+cos(deg2rad((float)$a['latitud']))*cos(deg2rad((float)$b['latitud']))*sin($dlon/2)**2;return 6371*2*asin(sqrt(min(1,max(0,$x))));}
function history_page():void { ?><section class="container page-intro"><span class="eyebrow">TERRITORIO · CULTURA · MEMORIA</span><h1>La memoria de un territorio.</h1><p>Chavín de Huántar, un punto de partida para conocer el patrimonio de Áncash.</p></section><section class="container section compact detail-grid"><article class="prose"><img class="history-art" src="<?=e(url('assets/landscape.svg'))?>" alt="Ilustración artística de un paisaje andino"><h2>Conocer también es cuidar.</h2><p>GeoChavín organiza información arqueológica, histórica, cultural y natural del distrito de Chavín de Huántar, provincia de Huari, región Áncash, Perú. Buscamos facilitar una visita informada y respetuosa.</p><p>El sitio arqueológico de Chavín cuenta con una referencia en la Lista del Patrimonio Mundial de UNESCO. La reseña histórica detallada, su cronología y las indicaciones de visita se incorporarán después de cotejarlas con documentación oficial.</p><h3>Cómo trabajamos la información</h3><p>Una ficha publicada puede estar pendiente de verificación. Las coordenadas solo aparecen cuando tanto la ficha como su ubicación se han cotejado. Las fotografías requieren autor, licencia y fuente; las ilustraciones se identifican como tales.</p><h3>Turismo responsable</h3><p>Respeta la señalización, las indicaciones del personal y las restricciones de conservación. Confirma accesos, horarios y servicios con las entidades responsables antes del viaje.</p></article><aside class="info-panel"><span class="eyebrow">FUENTES Y TRANSPARENCIA</span><h3>Información que puedes contrastar.</h3><p><strong>UNESCO · Chavín (Archaeological Site)</strong></p><?=source_link('https://whc.unesco.org/en/list/330/')?><p class="notice">Referencia inicial pendiente de cotejo en esta instalación. La consulta en línea no estuvo disponible durante el desarrollo.</p><p>Fuentes oficiales propuestas para completar el inventario: Ministerio de Cultura, MINCETUR y autoridades locales. Su contenido no ha sido incorporado como verificado.</p><hr><h4>Privacidad</h4><p class="small-text">El GPS se usa solo en tu navegador. El sitio guarda sesiones y conteos de visualización sin almacenar coordenadas personales. Al activar una ruta externa, se enviarán origen y destino al proveedor indicado. OpenStreetMap y las fuentes de fotografías reciben las solicitudes normales de tu navegador.</p></aside></section><?php }
function api():void {
 header('Content-Type: application/json; charset=utf-8');
 $items=attractions(mb_substr(query_string('q'),0,120),query_string('categoria'));
 $features=[];foreach($items as $a) {if(!$a['verificado']||!$a['posicion_verificada']||$a['latitud']===null||$a['longitud']===null)continue;$features[]=['type'=>'Feature','geometry'=>['type'=>'Point','coordinates'=>[(float)$a['longitud'],(float)$a['latitud']]],'properties'=>['id'=>(int)$a['id'],'nombre'=>$a['nombre'],'categoria'=>$a['categoria'],'url'=>url('?page=atractivo&id='.$a['id'])]];}
 echo json_encode(['type'=>'FeatureCollection','features'=>$features,'total_publicados'=>count($items),'pendientes_mapa'=>count($items)-count($features)],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);
}
function login_page():void {
 if(current_user())redirect('?page=admin');$error='';
 if($_SERVER['REQUEST_METHOD']==='POST') {check_csrf();try{throttle_login();$email=input_string('email');$password=$_POST['password']??'';if(!is_string($password)||strlen($password)>72)throw new DomainException('Credenciales no válidas.');$u=one('SELECT * FROM usuarios WHERE email=? AND activo=1',[mb_substr($email,0,190)]);$hash=$u['password_hash']??'$2y$10$92IXUNpkjO0rOQ5byMi.Ye4oKoEa3Ro9llC/.og/at2uheWG/igi';$ok=password_verify($password,$hash);if(!$u||!$ok)throw new DomainException('Correo o contraseña incorrectos.');if(password_needs_rehash($hash,PASSWORD_DEFAULT))execute('UPDATE usuarios SET password_hash=? WHERE id=?',[password_hash($password,PASSWORD_DEFAULT),$u['id']]);session_regenerate_id(true);$_SESSION['uid']=$u['id'];$_SESSION['csrf']=bin2hex(random_bytes(32));redirect('?page=admin');}catch(DomainException $ex){$error=$ex->getMessage();http_response_code(422);}}
